#!/usr/bin/env python3
"""
apply_sketch_core.py - Rounga constraint sketcher, stage 1 (the solver engine; no screens yet)

Adds a FreeCAD-Sketcher-style constraint solver written in pure Kotlin (no native code, no new libraries):
  core/sketch/Sketch.kt        points, lines, circles, arcs + 19 kinds of constraints and dimensions
  core/sketch/SketchSolver.kt  Levenberg-Marquardt solver, degrees-of-freedom count, conflict detection
  test/.../SketchSolverTest.kt 9 unit tests (numbers verified in a Python prototype of the same algorithm)
It only ADDS files. Nothing existing is edited, so it cannot change how the current app behaves.

Run from the ROOT of your repo (the folder containing settings.gradle.kts):   python apply_sketch_core.py
Undo, INSIDE YOUR REPO ONLY:   git checkout . && git clean -fd
"""
import base64, os, re, sys

PAYLOAD = {'Sketch.kt': '', 'SketchSolver.kt': '', 'SketchSolverTest.kt': ''}

def payload(name):
    return base64.b64decode(PAYLOAD[name]).decode("utf-8")

def find_one(name):
    hits = []
    for root, dirs, files in os.walk("app/src"):
        if name in files:
            hits.append(os.path.join(root, name))
    if len(hits) != 1:
        sys.exit("Expected exactly one %s under app/src, found %d. Are you in the repo root?" % (name, len(hits)))
    return hits[0]

shapes = find_one("Shapes.kt")
core_dir = os.path.dirname(shapes)
base_pkg = re.search(r"^package\s+([\w.]+)", open(shapes, encoding="utf-8").read(), re.M).group(1)
sketch_dir = os.path.join(core_dir, "sketch")
os.makedirs(sketch_dir, exist_ok=True)

def adapt(text):
    # the files are written for package feather.core.sketch; follow your project's real base package
    return text.replace("feather.core", base_pkg)

for name in ("Sketch.kt", "SketchSolver.kt"):
    path = os.path.join(sketch_dir, name)
    if os.path.exists(path):
        print("[skip] %s already exists" % name)
    else:
        open(path, "w", encoding="utf-8").write(adapt(payload(name)))
        print("[ok]   created", path)

# unit test goes beside the other tests, mirroring the main source folder layout
rel = os.path.relpath(core_dir, "app/src/main/java")
test_dir = os.path.join("app/src/test/java", rel, "sketch")
if os.path.isdir("app/src/test"):
    os.makedirs(test_dir, exist_ok=True)
    tp = os.path.join(test_dir, "SketchSolverTest.kt")
    if os.path.exists(tp):
        print("[skip] SketchSolverTest.kt already exists")
    else:
        open(tp, "w", encoding="utf-8").write(adapt(payload("SketchSolverTest.kt")))
        print("[ok]   created", tp)

print("\nDone. Next:  git add app && git commit -m 'Constraint sketch solver (stage 1)' && git push")
